package main

// nilIndex marks the absence of a neighbour in the recency list.
const nilIndex = -1

// entry is a node of the intrusive doubly linked recency list.
// Entries live in a slice and refer to each other by index, which keeps
// pointers out of the hot path and lets the garbage collector stay idle.
type entry struct {
	key, value string
	prev, next int
}

// Cache is a fixed-capacity least-recently-used cache.
// All operations run in O(1) expected time.
type Cache struct {
	capacity int
	index    map[string]int
	entries  []entry
	free     []int // indexes of recycled entries
	head     int   // most recently used
	tail     int   // least recently used
}

// NewCache returns an empty cache holding at most capacity keys.
func NewCache(capacity int) *Cache {
	hint := min(capacity+1, 1<<20)
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int, hint),
		entries:  make([]entry, 0, hint),
		head:     nilIndex,
		tail:     nilIndex,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set inserts or overwrites key, marks it most recently used and evicts
// the least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	i := c.alloc(key, value)
	c.index[key] = i
	c.pushFront(i)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc(key, value string) int {
	e := entry{key: key, value: value, prev: nilIndex, next: nilIndex}
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		c.entries[i] = e
		return i
	}
	c.entries = append(c.entries, e)
	return len(c.entries) - 1
}

func (c *Cache) remove(i int) {
	c.unlink(i)
	delete(c.index, c.entries[i].key)
	c.entries[i] = entry{prev: nilIndex, next: nilIndex}
	c.free = append(c.free, i)
}

func (c *Cache) moveToFront(i int) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int) {
	e := &c.entries[i]
	e.prev = nilIndex
	e.next = c.head
	if c.head != nilIndex {
		c.entries[c.head].prev = i
	}
	c.head = i
	if c.tail == nilIndex {
		c.tail = i
	}
}

func (c *Cache) unlink(i int) {
	e := &c.entries[i]
	if e.prev != nilIndex {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIndex {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIndex, nilIndex
}

// Command app simulates an LRU cache: it reads a capacity followed by a
// stream of SET/GET/DEL/SIZE commands from standard input and writes the
// results to standard output.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

const bufSize = 1 << 16

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

// run processes the whole input from r, writing command output to w.
func run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, bufSize), 1<<20)
	out := bufio.NewWriterSize(w, bufSize)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return err
		}
		return out.Flush()
	}
	capacity, err := strconv.Atoi(string(trim(sc.Bytes())))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}

	cache := NewCache(capacity)
	for sc.Scan() {
		if line := trim(sc.Bytes()); len(line) > 0 {
			execute(cache, out, line)
		}
	}
	if err := sc.Err(); err != nil {
		return err
	}
	return out.Flush()
}

// execute runs one command line against the cache. Unknown or malformed
// commands are ignored.
func execute(cache *Cache, out *bufio.Writer, line []byte) {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if ok {
			cache.Set(string(key), string(value))
		}
	case "GET":
		if v, ok := cache.Get(string(rest)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(rest)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}

// trim strips leading and trailing ASCII whitespace and control characters,
// matching the line handling of the original implementation.
func trim(b []byte) []byte {
	return bytes.TrimFunc(b, func(r rune) bool { return r <= ' ' })
}
